.calendar { display: inline-grid; gap: var(--s3); padding: var(--s4); border: 1px solid var(--foreground); background: var(--background); }
.calendar-head { display: flex; align-items: center; justify-content: space-between; gap: var(--s3); }
.calendar-title { font-weight: 500; font-size: var(--text-sm); }
.calendar-nav { width: var(--s6); height: var(--s6); border: 1px solid var(--rule); }
.calendar-nav:hover { border-color: var(--foreground); }
.calendar-grid { border-collapse: collapse; }
.calendar-grid th { font-size: var(--text-xs); font-weight: 400; color: var(--muted); padding: var(--s1) 0; text-transform: uppercase; }
.calendar-grid td { padding: 0; text-align: center; }
.calendar-day { width: var(--s6); height: var(--s6); font-size: var(--text-sm); }
.calendar-day:hover:not(:disabled) { background: var(--wash-2); }
.calendar-day[data-outside] { color: var(--muted); }
.calendar-day[data-today] { box-shadow: inset 0 0 0 1px var(--accent); }
.calendar-day[aria-pressed="true"] { background: var(--foreground); color: var(--background); }
.calendar-day:disabled { opacity: 0.35; cursor: not-allowed; }
.calendar-day:focus-visible, .calendar-nav:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
[dir="rtl"] .calendar-nav { transform: scaleX(-1); }

